#:package ClosedXML@0.105.1
#:property PublishAot=false
#:property PublishTrimmed=false

using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;
using ClosedXML.Excel;
using ClosedXML.Excel.Drawings;

// ============================================================================
// TASK 4 | INCIDENT FORENSICS / RATES DESK QUALITY CONTROL
// .NET 10 single-file app | ClosedXML 0.105.1 | No VBA
// Source: Excel_Template_Output/task4_snapshot.json
// Generated by: Task4_Jupyter_Export_Cell in incident_forensics.ipynb
//
// IMPORTANT CONTROL: Detection screens use the raw feed and recorded blotter.
// The incident log and corrected feed/book are EVALUATION-ONLY, i.e. post hoc.
// ============================================================================

string root = Environment.GetEnvironmentVariable("RAD_RISK_ROOT")
    ?? Directory.GetCurrentDirectory();
string outputDir = Path.Combine(root, "Excel_Template_Output");
string input = Path.Combine(outputDir, "task4_snapshot.json");
if (!File.Exists(input))
    throw new FileNotFoundException("Run the Task 4 Python JSON export cell first.", input);

var d = JsonSerializer.Deserialize<ForensicsSnapshot>(File.ReadAllText(input))
    ?? throw new InvalidOperationException("Cannot deserialize Task 4 JSON.");

string[] screens = { "PNL_FIXED", "PNL_SCALED", "STALE", "KINK", "LATE" };
var days = d.Daily.OrderBy(x => x.Date, StringComparer.Ordinal).ToList();
var cases = d.IncidentsEvaluationOnly.OrderBy(x => x.Id, StringComparer.Ordinal).ToList();
if (days.Count != d.ReportDays || days.Count == 0 || cases.Count != 6 ||
    d.FitNoiseBp <= 0 || d.TrainingStdUnexplained <= 0 ||
    d.SigmaThreshold <= 0 || d.StaleMinDays < 2 || d.KinkLimitBp <= 0)
    throw new InvalidOperationException("Input metadata invalid: day count, six cases or screening controls.");
if (days.Select(x => x.Date).Distinct().Count() != days.Count ||
    days.Any(x => x.Date.Length != 10 || !x.Date.StartsWith("2024-", StringComparison.Ordinal)))
    throw new InvalidOperationException("Expected unique ISO dates for 2024 report mornings.");
foreach (var day in days)
{
    if (!double.IsFinite(day.ReportedPnl) || !double.IsFinite(day.PredictedPnl) ||
        !double.IsFinite(day.Unexplained) || !double.IsFinite(day.ZScore) ||
        Math.Abs(day.ReportedPnl - day.PredictedPnl - day.Unexplained) > 0.01)
        throw new InvalidOperationException($"Task 3 P&L reconciliation fails: {day.Date}");
}
if (days.Count(x => x.Flags.PnlFixed) != 49 || days.Count(x => x.Flags.PnlScaled) != 34)
    throw new InvalidOperationException("2024 baseline P&L screen counts differ from Task 3 (49/34).");
if (!double.IsFinite(d.ClosingVar.AsReceived) ||
    !double.IsFinite(d.ClosingVar.FeedCorrected) ||
    !double.IsFinite(d.ClosingVar.FeedAndBookCorrected) ||
    d.ClosingVar.FeedAndBookCorrected <= 0)
    throw new InvalidOperationException("Invalid retrospective VaR comparison.");

int fixedCount = days.Count(x => x.Flags.PnlFixed);
int scaledCount = days.Count(x => x.Flags.PnlScaled);
int staleCount = days.Count(x => x.Flags.Stale);
int kinkCount = days.Count(x => x.Flags.Kink);
int lateCount = days.Count(x => x.Flags.Late);
int anyCount = days.Count(x => x.Flags.PnlFixed || x.Flags.PnlScaled ||
                                   x.Flags.Stale || x.Flags.Kink || x.Flags.Late);
double varGap = d.ClosingVar.FeedAndBookCorrected - d.ClosingVar.AsReceived;
double percentLow = 1 - d.ClosingVar.AsReceived / d.ClosingVar.FeedAndBookCorrected;

using var wb = new XLWorkbook();
var overview = wb.Worksheets.Add("01 Overview");
var timeline = wb.Worksheets.Add("02 Daily Screens");
var drill = wb.Worksheets.Add("03 Investigation");
var evidence = wb.Worksheets.Add("04 Evidence Register");
var review = wb.Worksheets.Add("05 Case Review");
var correction = wb.Worksheets.Add("06 VaR Impact");
var methodology = wb.Worksheets.Add("07 Methodology");
var pages = wb.Worksheets.Select(x => x.Name).ToArray();
foreach (var ws in wb.Worksheets)
    ForensicStyle.Setup(ws, d.AsOf, pages);

const int FIRST = 9;
int LAST = FIRST + days.Count - 1;

// ============================================================================
// 02 | DAILY SCREENING RESULTS - UNCORRECTED INPUTS ONLY
// Detection flags are intentionally preserved from Python's raw-data run.
// Column Q (hindsight incident IDs) NEVER enters a screen formula.
// ============================================================================
ForensicStyle.Banner(timeline, "DAILY SCREENING / RECEIVED FEED & BOOKED BLOTTER");
ForensicStyle.Section(timeline, "B7:R7", "2024 REPORT MORNINGS | RAW-DATA SCREENS | RETROSPECTIVE LABELS KEPT SEPARATE");
string[] dailyHeaders = {
    "REPORT DATE", "REPORTED P&L", "PREDICTED P&L", "UNEXPLAINED", "Z-SCORE",
    "PNL FIXED", "PNL SCALED", "STALE", "KINK", "LATE",
    "SCREEN COUNT", "ANY ALERT", "STALE EVIDENCE", "KINK EVIDENCE",
    "LATE TICKET", "OPS LOG / HINDSIGHT", "P&L CHECK"
};
for (int i = 0; i < dailyHeaders.Length; i++)
    timeline.Cell(8, 2 + i).Value = dailyHeaders[i];
ForensicStyle.Header(timeline, "B8:R8");
timeline.Column("B").Width = 17;
timeline.Columns("C:E").Width = 21;
timeline.Column("F").Width = 12;
timeline.Columns("G:K").Width = 15;
timeline.Columns("L:M").Width = 15;
timeline.Columns("N:P").Width = 26;
timeline.Column("Q").Width = 25;
timeline.Column("R").Width = 16;
for (int i = 0; i < days.Count; i++)
{
    int r = FIRST + i;
    var x = days[i];
    timeline.Cell(r, 2).Value = x.Date; // ISO text for locale-independent dropdown
    timeline.Cell(r, 3).Value = x.ReportedPnl;
    timeline.Cell(r, 4).Value = x.PredictedPnl;
    timeline.Cell(r, 5).Value = x.Unexplained;
    timeline.Cell(r, 6).Value = x.ZScore;
    ForensicStyle.Stripe(timeline, r, 2, 18, i);
    bool[] flags = { x.Flags.PnlFixed, x.Flags.PnlScaled, x.Flags.Stale,
                     x.Flags.Kink, x.Flags.Late };
    for (int s = 0; s < 5; s++)
    {
        var cell = timeline.Cell(r, 7 + s);
        cell.Value = flags[s] ? "RED" : "-";
        if (flags[s]) ForensicStyle.Danger(cell);
    }
    timeline.Cell(r, 12).FormulaA1 = $"COUNTIF(G{r}:K{r},\"RED\")";
    timeline.Cell(r, 13).FormulaA1 = $"IF(L{r}>0,\"INVESTIGATE\",\"CLEAR\")";
    timeline.Cell(r, 14).Value = x.StaleEvidence;
    timeline.Cell(r, 15).Value = x.KinkEvidence;
    timeline.Cell(r, 16).Value = x.LateTickets;
    timeline.Cell(r, 17).Value = x.IncidentIdsEvaluationOnly;
    timeline.Cell(r, 18).FormulaA1 = $"IF(ABS(C{r}-D{r}-E{r})<0.01,\"PASS\",\"CHECK\")";
    timeline.Range(r, 3, r, 5).Style.NumberFormat.Format = ForensicStyle.Money;
    timeline.Cell(r, 6).Style.NumberFormat.Format = "+0.0;-0.0;0.0";
    if (!string.IsNullOrEmpty(x.IncidentIdsEvaluationOnly))
        timeline.Cell(r, 17).Style.Fill.BackgroundColor = XLColor.FromHtml("#FFF0D7");
    timeline.Row(r).Height = 22;
}
timeline.Range(8, 2, LAST, 18).SetAutoFilter();
timeline.SheetView.FreezeRows(8);

// ============================================================================
// 03 | INVESTIGATION CONSOLE - DATE SELECTOR, LIVE FORMULA LOOKUPS
// The dropdown has a same-sheet hidden date list to avoid Excel 255-char
// literal-list limits and cross-worksheet validation portability issues.
// ============================================================================
ForensicStyle.Banner(drill, "INVESTIGATION CONSOLE / REPORT DATE DRILLDOWN");
ForensicStyle.Section(drill, "B7:M7", "SELECT A DATE IN C9 | TRACE THE SCREEN SIGNAL AND UNDERLYING RAW EVIDENCE");
drill.Column("B").Width = 31;
drill.Column("C").Width = 20;
drill.Column("F").Width = 28;
drill.Column("G").Width = 21;
drill.Column("J").Width = 24;
drill.Columns("K:M").Width = 16;
for (int i = 0; i < days.Count; i++)
    drill.Cell(FIRST + i, 52).Value = days[i].Date;
drill.Column("AZ").Hide();
drill.Cell("B9").Value = "REPORT DATE";
drill.Cell("C9").Value = days[^1].Date;
drill.Cell("C9").CreateDataValidation().List(drill.Range($"AZ{FIRST}:AZ{LAST}"));
ForensicStyle.Input(drill.Cell("C9"));
drill.Cell("F9").Value = "MATCHED DAY INDEX";
drill.Cell("G9").FormulaA1 = $"IFERROR(MATCH(C9,$AZ${FIRST}:$AZ${LAST},0),0)";
drill.Cell("J9").Value = "SCREEN STATUS";
drill.Cell("K9").FormulaA1 = "IF(G9=0,\"INVALID DATE\",IF(G18>0,\"INVESTIGATE\",\"CLEAR\"))";
string Lookup(string col) =>
    $"IF($G$9=0,\"\",INDEX('02 Daily Screens'!${col}${FIRST}:${col}${LAST},$G$9))";
ForensicStyle.Section(drill, "B12:M12", "REPORTED P&L VS MODEL / SCREENING EVIDENCE");
string[] metricLabels = { "Reported P&L", "Predicted P&L", "Unexplained P&L", "Noise-normalized Z" };
string[] metricColumns = { "C", "D", "E", "F" };
for (int i = 0; i < metricLabels.Length; i++)
{
    int r = 14 + i;
    drill.Cell(r, 2).Value = metricLabels[i];
    drill.Cell(r, 7).FormulaA1 = Lookup(metricColumns[i]);
    drill.Cell(r, 7).Style.NumberFormat.Format = i < 3 ? ForensicStyle.Money : "+0.00;-0.00;0.00";
    ForensicStyle.Stripe(drill, r, 2, 10, i);
}
drill.Cell("B18").Value = "ACTIVE SCREEN COUNT";
drill.Cell("G18").FormulaA1 = Lookup("L");
ForensicStyle.Total(drill, 18, 2, 10);
ForensicStyle.Section(drill, "B21:M21", "FIVE INDEPENDENT SCREENS / BASELINE RULES");
string[] screenLabels = { "P&L Fixed / 3.5 sigma", "P&L Risk-Scaled / 3.5 sigma",
                          "Stale Vertex / 3 tiny moves", "Curve Kink / >8 bp", "Late Booking / booked after trade" };
for (int i = 0; i < 5; i++)
{
    int r = 23 + i;
    drill.Cell(r, 2).Value = screenLabels[i];
    drill.Cell(r, 7).FormulaA1 = Lookup(((char)('G' + i)).ToString());
    ForensicStyle.Stripe(drill, r, 2, 10, i);
}
ForensicStyle.Section(drill, "B30:M30", "SOURCE EVIDENCE / WHAT TRIGGERED THE ALERT");
drill.Cell("B32").Value = "Stale Vertex";
drill.Cell("G32").FormulaA1 = Lookup("N");
drill.Cell("B33").Value = "Kink Jump (bp)";
drill.Cell("G33").FormulaA1 = Lookup("O");
drill.Cell("B34").Value = "Late Ticket";
drill.Cell("G34").FormulaA1 = Lookup("P");
drill.Cell("B37").Value = "KNOWN INCIDENT ID / HINDSIGHT";
drill.Cell("G37").FormulaA1 = Lookup("Q");
drill.Cell("G37").Style.Fill.BackgroundColor = XLColor.FromHtml("#FFF0D7");
ForensicStyle.Section(drill, "B40:M40", "INTERPRETATION & CONTROL BOUNDARY");
ForensicStyle.Note(drill, 42, "RED = potential exception requiring investigation, not proof that the market feed or booking is wrong.");
ForensicStyle.Note(drill, 44, "The ops incident ID is a retrospective evaluation label. No detection rule uses the incident log.");
ForensicStyle.Note(drill, 46, "Fixed and scaled P&L flags use the 2023 calibration and a locked 3.5-sigma baseline.");

// ============================================================================
// 04 | RAW-EVIDENCE REGISTER - FEED SCREENS AND TRADE TIMESTAMPS
// ============================================================================
ForensicStyle.Banner(evidence, "EVIDENCE REGISTER / OBSERVED MARKET AND BOOKING SIGNALS");
evidence.Columns("B:I").Width = 22;
evidence.Column("J").Width = 29;
ForensicStyle.Section(evidence, "B7:J7", "STALE RUNS | THREE CONSECUTIVE CHANGES UNDER 0.02 BP");
string[] staleHeaders = { "VERTEX", "FIRST TINY MOVE", "LAST TINY MOVE", "LENGTH", "EARLIEST ALERT" };
for (int i = 0; i < staleHeaders.Length; i++) evidence.Cell(9, i + 2).Value = staleHeaders[i];
ForensicStyle.Header(evidence, "B9:F9");
int sr = 10;
foreach (var x in d.StaleRuns)
{
    evidence.Cell(sr, 2).Value = x.Vertex;
    evidence.Cell(sr, 3).Value = x.First;
    evidence.Cell(sr, 4).Value = x.Last;
    evidence.Cell(sr, 5).Value = x.Length;
    evidence.Cell(sr, 6).Value = x.AlertDate ?? "";
    ForensicStyle.Stripe(evidence, sr, 2, 6, sr - 10);
    sr++;
}
int kinkSection = Math.Max(18, sr + 3);
ForensicStyle.Section(evidence, $"B{kinkSection}:J{kinkSection}", "CURVE-KINK JUMPS | DAILY KINK CHANGE > 8 BP");
string[] kinkHeaders = { "DATE", "VERTEX", "KINK CHANGE (BP)" };
for (int i = 0; i < kinkHeaders.Length; i++)
    evidence.Cell(kinkSection + 2, i + 2).Value = kinkHeaders[i];
ForensicStyle.Header(evidence, $"B{kinkSection + 2}:D{kinkSection + 2}");
int kr = kinkSection + 3;
foreach (var x in d.KinkJumps)
{
    evidence.Cell(kr, 2).Value = x.Date;
    evidence.Cell(kr, 3).Value = x.Vertex;
    evidence.Cell(kr, 4).Value = x.ChangeBp;
    evidence.Cell(kr, 4).Style.NumberFormat.Format = "+0.0;-0.0;0.0";
    ForensicStyle.Stripe(evidence, kr, 2, 4, kr - kinkSection - 3);
    kr++;
}
int lateSection = Math.Max(27, kr + 3);
ForensicStyle.Section(evidence, $"B{lateSection}:J{lateSection}", "LATE-BOOKED TICKETS | FIRST BOOKED DATE AFTER TRADE DATE");
string[] lateHeaders = { "TICKET", "TRADED", "BOOKED", "BOND", "FACE (USD M)", "LAG (BUSINESS DAYS)" };
for (int i = 0; i < lateHeaders.Length; i++)
    evidence.Cell(lateSection + 2, i + 2).Value = lateHeaders[i];
ForensicStyle.Header(evidence, $"B{lateSection + 2}:G{lateSection + 2}");
int lr = lateSection + 3;
foreach (var x in d.LateBookings)
{
    evidence.Cell(lr, 2).Value = x.Ticket;
    evidence.Cell(lr, 3).Value = x.Traded;
    evidence.Cell(lr, 4).Value = x.Booked;
    evidence.Cell(lr, 5).Value = x.Bond;
    evidence.Cell(lr, 6).Value = x.FaceM;
    evidence.Cell(lr, 7).Value = x.LagBusinessDays;
    ForensicStyle.Stripe(evidence, lr, 2, 7, lr - lateSection - 3);
    lr++;
}
ForensicStyle.Note(evidence, lr + 3, "This register contains observable events only, not vendor-corrected yields or the ops grading key.");

// ============================================================================
// 05 | RETROSPECTIVE CASE REVIEW (GROUND TRUTH, NOT SCREEN INPUT)
// Each first-hit is WITHIN the incident window; it is not causal proof.
// ============================================================================
ForensicStyle.Banner(review, "RETROSPECTIVE INCIDENT CASE REVIEW / SIX GROUND-TRUTH WINDOWS");
ForensicStyle.Section(review, "B7:P7", "POST-HOC OPERATIONS LOG | USED ONLY TO EVALUATE DETECTION TIMING");
review.Columns("B:E").Width = 19;
review.Column("F").Width = 12;
review.Columns("G:H").Width = 21;
review.Column("I").Width = 15;
review.Columns("J:L").Width = 20;
review.Columns("M:N").Width = 22;
review.Column("O").Width = 68;
string[] caseHeaders = {
    "INCIDENT", "KIND", "FIRST", "LAST", "DAYS", "FIRST FLAG", "SCREEN",
    "DELAY (DAYS)", "BOND", "BOOK ERROR (MM)", "IMPLIED DV01",
    "EXPECTED DV01", "WINDOW OBSERVATION", "OPS DESCRIPTION"
};
for (int i = 0; i < caseHeaders.Length; i++)
    review.Cell(9, 2 + i).Value = caseHeaders[i];
ForensicStyle.Header(review, "B9:O9");
for (int i = 0; i < cases.Count; i++)
{
    int r = 10 + i;
    var x = cases[i];
    var hits = screens.Select(s => (Screen: s, Hit: x.FirstHits.TryGetValue(s, out var h) ? h : null))
        .Where(z => z.Hit != null)
        .OrderBy(z => z.Hit!.Date, StringComparer.Ordinal)
        .ToList();
    var firstHit = hits.FirstOrDefault();
    review.Cell(r, 2).Value = x.Id;
    review.Cell(r, 3).Value = x.Kind;
    review.Cell(r, 4).Value = x.First;
    review.Cell(r, 5).Value = x.Last;
    review.Cell(r, 6).Value = x.Days;
    review.Cell(r, 7).Value = firstHit.Hit?.Date ?? "-";
    review.Cell(r, 8).Value = firstHit.Hit != null ? firstHit.Screen : "NOT FLAGGED";
    if (firstHit.Hit != null) review.Cell(r, 9).Value = firstHit.Hit.DelayDays;
    review.Cell(r, 10).Value = x.Bond ?? "FEED";
    review.Cell(r, 11).Value = x.ErrorM;
    if (x.ImpliedDv01.HasValue) review.Cell(r, 12).Value = x.ImpliedDv01.Value;
    if (x.ExpectedDv01.HasValue) review.Cell(r, 13).Value = x.ExpectedDv01.Value;
    review.Cell(r, 14).Value = hits.Count > 0 ? "At least one screen fired inside window" : "No screen inside window";
    review.Cell(r, 15).Value = x.What;
    review.Cell(r, 15).Style.Alignment.WrapText = true;
    review.Range(r, 11, r, 13).Style.NumberFormat.Format = ForensicStyle.Number;
    review.Row(r).Height = 39;
    ForensicStyle.Stripe(review, r, 2, 15, i);
}
ForensicStyle.Section(review, "B19:N19", "FIRST FIRING DATE BY SCREEN / DAYS FROM INCIDENT FIRST MORNING");
string[] hitHeaders = { "CASE", "PNL FIXED", "PNL SCALED", "STALE", "KINK", "LATE" };
for (int i = 0; i < hitHeaders.Length; i++) review.Cell(21, i + 2).Value = hitHeaders[i];
ForensicStyle.Header(review, "B21:G21");
for (int i = 0; i < cases.Count; i++)
{
    int r = 22 + i;
    review.Cell(r, 2).Value = cases[i].Id;
    for (int j = 0; j < screens.Length; j++)
    {
        var hit = cases[i].FirstHits.TryGetValue(screens[j], out var h) ? h : null;
        review.Cell(r, j + 3).Value = hit == null ? "-" : $"{hit.Date} / +{hit.DelayDays}";
    }
    ForensicStyle.Stripe(review, r, 2, 7, i);
}
ForensicStyle.Section(review, "B30:N30", "LIMITATION: HINDSIGHT CASE REVIEW IS NOT A REAL-TIME CLASSIFIER");
ForensicStyle.Note(review, 32, "The six incident windows were supplied AFTER year-end. They are an evaluation key, never screening inputs.");
ForensicStyle.Note(review, 34, "A P&L or kink signal in an incident window may be coincidental; review the market data and trade evidence.");
ForensicStyle.Note(review, 36, "For booking cases, implied DV01 is an approximate regression, not a uniquely identified missing position.");

// ============================================================================
// 06 | RETROSPECTIVE VaR CORRECTION BRIDGE
// ============================================================================
ForensicStyle.Banner(correction, "REMEDIATION IMPACT / HISTORICAL VaR RESTATEMENT");
ForensicStyle.Section(correction, "B7:N7", "YEAR-END 1-DAY 99% HS VaR | RAW FEED -> CORRECTED FEED -> CORRECTED BOOK");
correction.Column("B").Width = 35;
correction.Columns("E:G").Width = 22;
correction.Column("J").Width = 33;
correction.Cell("B10").Value = "01 | As received: feed + booked portfolio";
correction.Cell("F10").Value = d.ClosingVar.AsReceived;
correction.Cell("B12").Value = "02 | Corrected feed, original booked portfolio";
correction.Cell("F12").Value = d.ClosingVar.FeedCorrected;
correction.Cell("B14").Value = "03 | Corrected feed + corrected position book";
correction.Cell("F14").Value = d.ClosingVar.FeedAndBookCorrected;
ForensicStyle.Total(correction, 14, 2, 8);
correction.Cell("B17").Value = "VaR change from feed corrections";
correction.Cell("F17").FormulaA1 = "F12-F10";
correction.Cell("B18").Value = "Further VaR change from book correction";
correction.Cell("F18").FormulaA1 = "F14-F12";
correction.Cell("B19").Value = "Total correction impact";
correction.Cell("F19").FormulaA1 = "F14-F10";
correction.Cell("B20").Value = "Original VaR understatement / corrected VaR";
correction.Cell("F20").FormulaA1 = "IF(F14>0,1-F10/F14,0)";
correction.Range("F10:F19").Style.NumberFormat.Format = ForensicStyle.Money;
correction.Cell("F20").Style.NumberFormat.Format = "0.0%";
ForensicStyle.Section(correction, "B23:N23", "BAD-PRINT SCENARIO / SCENARIO TAIL REVIEW");
correction.Cell("B25").Value = "Historical bad-print date";
correction.Cell("F25").Value = d.BadPrintScenario.Date;
correction.Cell("B26").Value = "Rank in original 500-day VaR window";
correction.Cell("F26").Value = d.BadPrintScenario.Rank;
correction.Cell("B27").Value = "P&L of that scenario";
correction.Cell("F27").Value = d.BadPrintScenario.Pnl;
correction.Cell("B28").Value = "Fifth-worst historical scenario";
correction.Cell("F28").Value = d.BadPrintScenario.FifthWorstPnl;
correction.Cell("B29").Value = "Sixth-worst historical scenario";
correction.Cell("F29").Value = d.BadPrintScenario.SixthWorstPnl;
correction.Range("F27:F29").Style.NumberFormat.Format = ForensicStyle.Money;
ForensicStyle.Section(correction, "B33:N33", "METHODOLOGY NOTE / CORRECTIONS ARE NOT FUTURE-PREDICTIVE");
ForensicStyle.Note(correction, 35, "The corrected curve points and missing/amended trades are supplied hindsight evidence, not live inputs.");
ForensicStyle.Note(correction, 37, "VaR is re-estimated using the corrected 500 historical curve moves and the corrected closing ladder.");
ForensicStyle.Note(correction, 39, "VaR difference depends on the 500-day scenario ranking; it is not a P&L realized loss.");

// ============================================================================
// 01 | EXECUTIVE OVERVIEW / ACTIONABLE SCREENING SUMMARY
// ============================================================================
ForensicStyle.Banner(overview, "RATES DESK / INCIDENT FORENSICS & DATA QUALITY");
ForensicStyle.Section(overview, "B7:V7", "RAW-FEED SCREENING | 2024 REVIEW PERIOD | SIX RETROSPECTIVE INVESTIGATION WINDOWS");
ForensicStyle.Kpi(overview, "B9:F9", "B10:F12", "REPORT MORNINGS", days.Count, false);
ForensicStyle.Kpi(overview, "H9:L9", "H10:L12", "DAYS WITH >=1 ALERT", anyCount, false);
ForensicStyle.Kpi(overview, "N9:R9", "N10:R12", "REVIEWED OPS CASES", cases.Count, false);
ForensicStyle.Section(overview, "B15:R15", "SCREEN TRIGGER COUNTS / NOT INCIDENT COUNTS");
string[] countNames = { "P&L FIXED", "P&L SCALED", "STALE", "KINK", "LATE" };
int[] counts = { fixedCount, scaledCount, staleCount, kinkCount, lateCount };
for (int i = 0; i < 5; i++)
{
    int r = 17 + i;
    overview.Cell(r, 2).Value = countNames[i];
    overview.Cell(r, 8).Value = counts[i];
    overview.Cell(r, 11).Value = (double)counts[i] / days.Count;
    overview.Cell(r, 11).Style.NumberFormat.Format = "0.0%";
    ForensicStyle.Stripe(overview, r, 2, 15, i);
}
overview.Cell("H16").Value = "FLAGGED MORNINGS";
overview.Cell("K16").Value = "SHARE OF YEAR";
ForensicStyle.Section(overview, "B24:R24", "REMEDIATION IMPACT / 2024-12-31 RETROSPECTIVE VaR");
overview.Cell("B26").Value = "As-received VaR";
overview.Cell("H26").Value = d.ClosingVar.AsReceived;
overview.Cell("B27").Value = "Fully corrected VaR";
overview.Cell("H27").Value = d.ClosingVar.FeedAndBookCorrected;
overview.Cell("B28").Value = "Difference (corrected - received)";
overview.Cell("H28").Value = varGap;
overview.Cell("B29").Value = "As-received understatement";
overview.Cell("H29").Value = percentLow;
overview.Range("H26:H28").Style.NumberFormat.Format = ForensicStyle.Money;
overview.Cell("H29").Style.NumberFormat.Format = "0.0%";
ForensicStyle.Section(overview, "B32:R32", "2024 SCREEN TIMELINE | SHADED PERIODS ARE KNOWN ONLY RETROSPECTIVELY");
if (!string.IsNullOrWhiteSpace(d.ScreenChart))
{
    using var imageStream = new MemoryStream(Convert.FromBase64String(d.ScreenChart));
    overview.AddPicture(imageStream, XLPictureFormat.Png)
        .MoveTo(overview.Cell("B34")).Scale(0.67);
}
ForensicStyle.Note(overview, 55, "READ THIS FIRST: screen flags are hypotheses for investigation, not confirmed errors.");
ForensicStyle.Note(overview, 57, "The operations log and corrected feed/book are displayed only in retrospective review sheets.");
ForensicStyle.Note(overview, 59, "This is a simulated training example, not a live control or trading authorization system.");

// ============================================================================
// 07 | METHODOLOGY, DATA LINEAGE, CONTROLS AND LIMITATIONS
// ============================================================================
ForensicStyle.Banner(methodology, "TASK 4 / METHOD DEFINITIONS & CONTROL BOUNDARIES");
methodology.Column("B").Width = 27;
methodology.Column("C").Width = 27;
methodology.Column("D").Width = 85;
ForensicStyle.Section(methodology, "B7:D7", "THE FIVE PROSPECTIVE SCREENS / RAW INPUTS ONLY");
string[,] rules = {
    { "PNL_FIXED", "2023 baseline", "Flag if |unexplained P&L| exceeds 3.5 x standard deviation of 2023 unexplained P&L." },
    { "PNL_SCALED", "2023 fitted noise", "Flag if |unexplained / noise-adjusted SD| exceeds 3.5; noise SD depends on yesterday's key-rate ladder." },
    { "STALE", "Received zero curve", "Flag on the third morning of consecutive moves smaller than 0.0002 percentage points (0.02 bp)." },
    { "KINK", "Received zero curve", "Flag an interior curve vertex if the day-to-day change in its local maturity-interpolated kink exceeds 8 bp." },
    { "LATE", "Booked trade blotter", "Flag the original ticket when its first booking timestamp is after the stated trade date." }
};
methodology.Cell("B9").Value = "SCREEN";
methodology.Cell("C9").Value = "DATA INPUT";
methodology.Cell("D9").Value = "RULE / DECISION PURPOSE";
ForensicStyle.Header(methodology, "B9:D9");
for (int i = 0; i < rules.GetLength(0); i++)
{
    int r = 10 + i;
    for (int j = 0; j < 3; j++) methodology.Cell(r, 2 + j).Value = rules[i, j];
    methodology.Cell(r, 4).Style.Alignment.WrapText = true;
    methodology.Row(r).Height = 37;
    ForensicStyle.Stripe(methodology, r, 2, 4, i);
}
ForensicStyle.Section(methodology, "B17:D17", "SCREENING / EVALUATION / CORRECTION ARE SEPARATE PHASES");
string[,] stages = {
    { "01 | Screening", "As received", "Curve feed, reported P&L and booked positions. No information from the future or from corrected data." },
    { "02 | Evaluation", "Ops incident log", "After-year-end known incident windows identify whether and when each screen fired. Overlap is not causal proof." },
    { "03 | Correction", "Vendor + operations", "Apply externally supplied corrected zero-curve points, amended tickets and missing ticket to estimate revised closing VaR." },
    { "04 | Decision", "Human review", "Investigate actual price and booking evidence, identify ownership, then decide whether to remediate or restate." }
};
for (int i = 0; i < stages.GetLength(0); i++)
{
    int r = 19 + i;
    for (int j = 0; j < 3; j++) methodology.Cell(r, 2 + j).Value = stages[i, j];
    methodology.Cell(r, 4).Style.Alignment.WrapText = true;
    methodology.Row(r).Height = 42;
    ForensicStyle.Stripe(methodology, r, 2, 4, i);
}
ForensicStyle.Section(methodology, "B26:D26", "METRICS / UNITS / MODEL LIMITATIONS");
string[,] notes = {
    { "Unexplained P&L", "USD", "Reported P&L minus [carry - previous Key-Rate DV01 x today's yield changes]." },
    { "Z-score", "SD units", "Unexplained P&L divided by sqrt(2) x fitted noise(bp) x Euclidean norm of prior-day DV01 ladder." },
    { "Implied missing DV01", "USD/bp", "Through-origin regression of unexplained P&L on the average daily parallel curve move. This is only an approximation." },
    { "VaR", "USD loss", "Fifth-worst scenario of 500 daily yield-curve moves, using a linear key-rate DV01 approximation." },
    { "Incident windows", "Report days", "Six periods supplied by the simulated retrospective operations log. Not valid as model features." },
    { "Coverage", "2024", "Historical model screening. No claim of real-time monitoring, execution controls or production accuracy." }
};
for (int i = 0; i < notes.GetLength(0); i++)
{
    int r = 28 + i;
    for (int j = 0; j < 3; j++) methodology.Cell(r, 2 + j).Value = notes[i, j];
    methodology.Cell(r, 4).Style.Alignment.WrapText = true;
    methodology.Row(r).Height = 40;
    ForensicStyle.Stripe(methodology, r, 2, 4, i);
}
ForensicStyle.Note(methodology, 36, "SOURCE: educational RiskHub fixed-income simulation; calculations exported by Python and rendered by ClosedXML.");
ForensicStyle.Note(methodology, 38, "CONSTRAINT: no credit-spread, funding, liquidity, convexity or real-time broker connectivity model.");

// Recalculate formulas when opened in Excel (ClosedXML does not cache all formulas).
wb.CalculateMode = XLCalculateMode.Auto;
Directory.CreateDirectory(outputDir);
string destination = Path.Combine(outputDir,
    $"RatesDesk_IncidentForensics_Task4_{d.AsOf}.xlsx");
wb.SaveAs(destination);
Console.WriteLine("SUCCESS: Task 4 workbook generated");
Console.WriteLine("Excel: " + destination);
Console.WriteLine($"Report days: {days.Count} | Evaluation cases: {cases.Count}");
Console.WriteLine($"Fixed / Scaled / Stale / Kink / Late: {fixedCount} / {scaledCount} / {staleCount} / {kinkCount} / {lateCount}");
Console.WriteLine($"VaR: received USD {d.ClosingVar.AsReceived:N0} -> corrected USD {d.ClosingVar.FeedAndBookCorrected:N0}");

