public static class ForensicStyle
{
    public const string Money = "$#,##0;[Red]($#,##0);-";
    public const string Number = "+#,##0;[Red](#,##0);-";
    static readonly XLColor Navy = XLColor.FromHtml("#14263D");
    static readonly XLColor Blue = XLColor.FromHtml("#244767");
    static readonly XLColor Pale = XLColor.FromHtml("#EAF1F7");
    static readonly XLColor Muted = XLColor.FromHtml("#64748B");
    public static void Setup(IXLWorksheet ws, string asOf, string[] pages)
    {
        ws.ShowGridLines = false;
        ws.Style.Font.FontName = "Aptos";
        ws.Style.Font.FontSize = 10;
        ws.Style.Font.FontColor = Navy;
        ws.Column(1).Width = 3;
        ws.Columns("B:V").Width = 12;
        ws.Row(2).Height = 30;
        ws.Row(3).Height = 26;
        ws.Row(5).Height = 29;
        ws.Cell("B4").Value = $"AS OF {asOf}  |  2024 HISTORICAL REVIEW  |  SIMULATED RATES DESK";
        ws.Cell("B4").Style.Font.FontColor = Muted;
        for (int i = 0; i < pages.Length; i++)
        {
            int firstCol = 2 + i * 3;
            var area = ws.Range(5, firstCol, 5, firstCol + 2);
            area.Merge();
            area.FirstCell().FormulaA1 = $"HYPERLINK(\"#'{pages[i]}'!B2\",\"{(i+1):00} {Label(pages[i])}\")";
            area.Style.Fill.BackgroundColor = Pale;
            area.Style.Font.FontColor = Blue;
            area.Style.Font.Bold = true;
            area.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        }
    }
    static string Label(string name) => name.Split(' ', 2)[^1].ToUpperInvariant();
    public static void Banner(IXLWorksheet ws, string title)
    {
        var range = ws.Range("B2:V3");
        range.Merge();
        range.FirstCell().Value = title;
        range.Style.Fill.BackgroundColor = Navy;
        range.Style.Font.FontColor = XLColor.White;
        range.Style.Font.Bold = true;
        range.Style.Font.FontSize = 18;
        range.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
    }
    public static void Section(IXLWorksheet ws, string region, string label)
    {
        var range = ws.Range(region);
        range.Merge();
        range.FirstCell().Value = label;
        range.Style.Fill.BackgroundColor = Blue;
        range.Style.Font.FontColor = XLColor.White;
        range.Style.Font.Bold = true;
        range.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
        range.Style.Font.FontSize = 10;
    }
    public static void Header(IXLWorksheet ws, string region)
    {
        var range = ws.Range(region);
        range.Style.Fill.BackgroundColor = Blue;
        range.Style.Font.FontColor = XLColor.White;
        range.Style.Font.Bold = true;
        range.Style.Alignment.WrapText = true;
        ws.Row(range.FirstCell().Address.RowNumber).Height = 36;
    }
    public static void Stripe(IXLWorksheet ws, int r, int c0, int c1, int index)
    {
        if (index % 2 == 0)
            ws.Range(r, c0, r, c1).Style.Fill.BackgroundColor = XLColor.FromHtml("#F5F8FB");
    }
    public static void Danger(IXLCell cell)
    {
        cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#FBE7E9");
        cell.Style.Font.FontColor = XLColor.FromHtml("#AE3449");
        cell.Style.Font.Bold = true;
    }
    public static void Input(IXLCell cell)
    {
        cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#E5F0FF");
        cell.Style.Font.FontColor = XLColor.FromHtml("#1255B0");
        cell.Style.Font.Bold = true;
    }
    public static void Total(IXLWorksheet ws, int r, int c0, int c1)
    {
        var range = ws.Range(r, c0, r, c1);
        range.Style.Fill.BackgroundColor = Pale;
        range.Style.Font.Bold = true;
        ws.Row(r).Height = 27;
    }
    public static void Kpi(IXLWorksheet ws, string header, string valueArea,
        string title, double number, bool money)
    {
        var h = ws.Range(header);
        h.Merge();
        h.FirstCell().Value = title;
        h.Style.Fill.BackgroundColor = Pale;
        h.Style.Font.FontColor = Muted;
        h.Style.Font.Bold = true;
        var v = ws.Range(valueArea);
        v.Merge();
        v.FirstCell().Value = number;
        v.Style.NumberFormat.Format = money ? Money : "#,##0";
        v.Style.Fill.BackgroundColor = Pale;
        v.Style.Font.FontSize = 22;
        v.Style.Font.Bold = true;
        v.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
        v.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
    }
    public static void Note(IXLWorksheet ws, int row, string content)
    {
        var range = ws.Range(row, 2, row, 22);
        range.Merge();
        range.FirstCell().Value = content;
        range.Style.Font.FontColor = Muted;
        range.Style.Font.FontSize = 10;
        range.Style.Alignment.WrapText = true;
        ws.Row(row).Height = 28;
    }
}
